#include <algorithm>
#include <set>
#include <string>
#include <tuple>
#include <vector>

struct Player { int id; std::string name; int score; };

// Highest score first; equal scores by smaller id. Strict: never true for equal pairs.
bool ranks_before(const Player& a, const Player& b) {
    if (a.score != b.score) return a.score > b.score;
    return a.id < b.id;
}

struct ById {                                     // for a set keyed by id.
    bool operator()(const Player& a, const Player& b) const {
        return std::tie(a.id) < std::tie(b.id);
    }
};

int main() {
    std::vector<Player> ps{{3, "Mei", 90}, {1, "Asha", 95}, {2, "Ravi", 90}};
    std::sort(ps.begin(), ps.end(), ranks_before);   // Asha, Ravi(2), Mei(3).
    std::set<Player, ById> roster(ps.begin(), ps.end());
}
